/*
 * config-ios.h — то, что у libopus обычно порождает `configure`.
 *
 * Автотулзы сюда не зовутся намеренно: кросс-сборка под iOS 6 из Linux
 * настраивается ими долго и непредсказуемо, а нужно нам ровно то, что ниже.
 * Файл подставляется ключом -DHAVE_CONFIG_H -include, см. tools/build-opus.sh.
 */

#ifndef LOVIT_OPUS_CONFIG_H
#define LOVIT_OPUS_CONFIG_H

#define OPUS_BUILD 1

/*
 * Счёт с плавающей точкой, а не целочисленный.
 *
 * FIXED_POINT быстрее на процессорах без FPU — но их среди устройств с
 * armv7 и arm64 нет вовсе, а звук у плавающего счёта чуть чище. Ровно так
 * же собран и декодер в клиенте под Windows Phone, и заодно это избавляет
 * от подкаталога silk/fixed целиком.
 */
/* #define FIXED_POINT 1 */

/*
 * Временные массивы — на стеке, размером по месту (C99).
 *
 * Другой вариант, USE_ALLOCA, делает то же самое через alloca(); третьего —
 * своего псевдостека — брать нельзя: он не потокобезопасен, а кодирование
 * идёт с фоновой очереди.
 */
#define VAR_ARRAYS 1

#define HAVE_LRINT 1
#define HAVE_LRINTF 1
#define HAVE_STDINT_H 1

/* Оптимизаций под конкретную архитектуру не берём: у них свои правила
 * сборки и ассемблерные файлы, а голос кодируется и обычным C заметно
 * быстрее реального времени. */

#define PACKAGE_VERSION "1.4"

#endif /* LOVIT_OPUS_CONFIG_H */
